output_text:
[
  {
    "id": "no_cart_in_single_file_shelf_aisles",
    "text": "Shopping carts are prohibited in single-file shelf aisles, i.e. narrow cells with shelves on both sides.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "no_enter_single_file_with_cart",
    "text": "An agent must not push a cart from a public aisle into a single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "enterSingleFileWithCart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileWithCart"
    }
  },
  {
    "id": "park_cart_only_at_upper_aisle_mouth",
    "text": "A cart may be set down only at the wide mouth of an upper single-file aisle.",
    "abstraction": {
      "state_properties": {
        "a1AisleMouth": "at(3,3)",
        "a2AisleMouth": "at(6,3)",
        "upperAisleMouth": {
          "or": [
            "a1AisleMouth",
            "a2AisleMouth"
          ]
        }
      },
      "events": {
        "releaseCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "releaseCart",
          {
            "not": "upperAisleMouth"
          }
        ]
      }
    }
  },
  {
    "id": "retrieve_cart_after_parking",
    "text": "After parking a cart for a narrow-aisle excursion, the agent is obliged to retrieve a cart before exiting.",
    "abstraction": {
      "state_properties": {
        "a1AisleMouth": "at(3,3)",
        "a2AisleMouth": "at(6,3)",
        "upperAisleMouth": {
          "or": [
            "a1AisleMouth",
            "a2AisleMouth"
          ]
        }
      },
      "events": {
        "parkCartAtMouth": {
          "pre": {
            "and": [
              "upperAisleMouth",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "takeCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCartAtMouth",
      "discharge": "takeCart"
    }
  },
  {
    "id": "no_walking_without_cart_except_aisle_excursion",
    "text": "Once a cart has been taken, walking without it is allowed only during the short excursion between a cart-parking mouth and the associated single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "a1AisleMouth": "at(3,3)",
        "a2AisleMouth": "at(6,3)",
        "upperAisleMouth": {
          "or": [
            "a1AisleMouth",
            "a2AisleMouth"
          ]
        },
        "cartExcursionZone": {
          "or": [
            "singleFileShelfAisle",
            "upperAisleMouth"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "MOVE",
          {
            "not": "hasCart"
          },
          {
            "not": "cartExcursionZone"
          }
        ]
      }
    }
  },
  {
    "id": "return_to_cart_after_on_foot_item",
    "text": "After collecting an item on foot inside a single-file shelf aisle, the agent is obliged to return to the aisle mouth and pick the cart back up.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "a1AisleMouth": "at(3,3)",
        "a2AisleMouth": "at(6,3)",
        "upperAisleMouth": {
          "or": [
            "a1AisleMouth",
            "a2AisleMouth"
          ]
        }
      },
      "events": {
        "onFootSingleFileItemInteraction": {
          "pre": {
            "and": [
              "singleFileShelfAisle",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "retrieveCartAtMouth": {
          "pre": {
            "and": [
              "upperAisleMouth",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "onFootSingleFileItemInteraction",
      "discharge": "retrieveCartAtMouth"
    }
  },
  {
    "id": "cart_required_for_broad_shelf_interaction",
    "text": "Shelf interactions from broad public aisles must be done while holding the cart.",
    "abstraction": {
      "state_properties": {
        "broadShelfAccess": {
          "and": [
            "adjShelf",
            {
              "ge": [
                "freeWidthH",
                2
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "broadShelfAccess",
          "INTERACT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "on_foot_item_interactions_only_single_file",
    "text": "If an agent interacts with merchandise while not holding a cart and still remains without the cart afterwards, that interaction must occur inside a single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "onFootItemInteraction": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "onFootItemInteraction",
          {
            "not": "singleFileShelfAisle"
          }
        ]
      }
    }
  }
]
